INSERT INTO products (category_id, name, slug, description, image_url, price_cents, currency, active)
SELECT c.id, d.name, d.slug, d.description, d.image_url, d.price_cents, 'ZAR', true
FROM demo_products d
JOIN categories c ON c.slug = d.category_slug
ON CONFLICT (slug) DO UPDATE
SET category_id = EXCLUDED.category_id,
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    image_url = EXCLUDED.image_url,
    price_cents = EXCLUDED.price_cents,
    currency = 'ZAR',
    active = true;
